import{_ as e,o as d,c as a,ag as r}from"./chunks/framework.BoXUJ6sC.js";const o="/beadv8_8_BBCC_BE/assets/23.BezYXzuN.svg",c="/beadv8_8_BBCC_BE/assets/02.Cbfg-TAC.png",i="/beadv8_8_BBCC_BE/assets/03.BdAxOTNd.png",s="/beadv8_8_BBCC_BE/assets/04.D0arfjna.png",l="/beadv8_8_BBCC_BE/assets/05.Bmf-4bcR.png",n="/beadv8_8_BBCC_BE/assets/24.q2fTsx1-.svg",h="/beadv8_8_BBCC_BE/assets/25.Bv5-GuDT.svg",p="/beadv8_8_BBCC_BE/assets/26.D8wh8XNV.svg",m="/beadv8_8_BBCC_BE/assets/27.BnJdgxMH.svg",B=JSON.parse('{"title":"전체 그림","description":"","frontmatter":{},"headers":[],"relativePath":"planning/architecture.md","filePath":"planning/architecture.md"}'),_={name:"planning/architecture.md"};function g(u,t,b,f,k,y){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="전체-그림" tabindex="-1">전체 그림 <a class="header-anchor" href="#전체-그림" aria-label="Permalink to &quot;전체 그림&quot;">​</a></h1><h2 id="_3-1-전체-구성" tabindex="-1">3.1 전체 구성 <a class="header-anchor" href="#_3-1-전체-구성" aria-label="Permalink to &quot;3.1 전체 구성&quot;">​</a></h2><p>세미의 <strong>모듈러 모놀리스</strong>(앱 1개 · 배포 1개 · DB 1개)에서 출발해, 도메인 사이 이벤트를 <strong>Kafka</strong>로 옮기고 서비스를 하나씩 떼어 내고 있습니다. 모든 요청은 <strong>API Gateway</strong>를 거치고, 서비스끼리는 서로 부르지 않습니다.</p><p><img src="'+o+'" alt="그림"></p><ul><li>요청은 화면 → <strong>API Gateway</strong>(dev 8083 · prod 8084) → 서비스로 갑니다. Gateway가 토큰 검증 · 무효화 확인 · 역할 검사 · CORS를 하고 검증된 회원 정보를 헤더로 넘깁니다. 서비스는 Gateway 뒤에서만 열린다는 전제입니다.</li><li>Gateway는 경로별로 보냅니다: <code>GET /api/v1/products</code> → search-service, 자녀 경로 → childprofile-service(dev), 나머지 → kidly-app. 결제 · 추천도 분리를 마치면 경로를 그대로 둔 채 넘깁니다.</li><li>도메인 사이는 Kafka 이벤트로만 주고받습니다(토픽은 3.3). 다른 도메인 정보는 이벤트로 받아 둔 복사본을 씁니다 (6.3).</li><li>서버는 EC2 2대입니다: t3.large(Docker Compose: Gateway · kidly-app · 검색 서비스 · PostgreSQL · Kafka)와 t3.medium(k3s: Elasticsearch · 모니터링). 상품 이미지는 S3, 배포는 GitHub Actions가 맡습니다.</li><li>검색 서비스(search-service)는 kidly-app과 따로 뜨는 Spring Boot 앱입니다. 앱 서버 t3.large의 docker compose에서 돌고(프로필 <code>search</code>, heap 512m), 서버 안 <code>127.0.0.1:8082</code>에만 열립니다.</li><li>Elasticsearch(공식 이미지 + nori)는 모니터링과 같은 t3.medium의 k3s에서 돕니다(namespace <code>search</code>, heap 1g, 데이터 10Gi). 검색 서비스는 VPC 안에서 NodePort 30920으로 붙고, 보안 그룹은 t3.large에서 오는 것만 받습니다.</li><li>지금은 dev만 켜져 있습니다. 배포는 앱 배포 워크플로가 Elasticsearch를 먼저 올린 뒤 검색 서비스를 올립니다. Elasticsearch 설정이나 이미지가 바뀌면 다시 뜨는 동안 2분쯤 검색이 끊깁니다.</li></ul><p>아래는 세미 때 구성(앱 1개 · EC2 1대)입니다. 참고로 남깁니다.</p><p><img src="'+c+'" alt="Kidly 아키텍처"></p><h2 id="_3-2-모듈-구성" tabindex="-1">3.2 모듈 구성 <a class="header-anchor" href="#_3-2-모듈-구성" aria-label="Permalink to &quot;3.2 모듈 구성&quot;">​</a></h2><table tabindex="0"><thead><tr><th>모듈</th><th>담당</th><th>한 줄 책임</th></tr></thead><tbody><tr><td>회원</td><td>maruhxn</td><td>로그인 · 가입 · 탈퇴 · 정지, 자녀 프로필, 판매자 승인, 가입 환영 메일 — member · childprofile · seller · notification 모듈. 자녀 프로필은 childprofile-service로 분리(dev), 인증은 auth 도메인으로 분리 중(#686)</td></tr><tr><td>상품</td><td>heojungseok</td><td>상품 · 옵션 · 재고, 상품 상세, 카테고리 · 상품 유형 · 항목 · 실측 항목 기준 데이터, 이미지 업로드 주소 (목록 · 검색은 검색 모듈로)</td></tr><tr><td>추천</td><td>heojungseok</td><td>사이즈 추천 · AI 상품 추천 · 함께 사면 좋은 상품, 활동 기록 · 선호 점수, 기준 옷 비교(2순위). recommend-service로 분리 중(#704)</td></tr><tr><td>주문</td><td>L2J92</td><td>장바구니 · 공용 장바구니(조르기), 주문, 배송(택배 조회), 구매확정, 판매자 부분 취소 — order · cart · delivery · wish 4개 컨텍스트(포트로만 연결, ArchUnit으로 고정)</td></tr><tr><td>결제</td><td>codes-gy</td><td>지갑(동결 포함), 충전 · 충전 취소, 주문 결제 · 환불, 정산금 입금, 토스 웹훅. payment-service로 분리 중</td></tr><tr><td>검색</td><td>codes-gy</td><td>상품 목록 검색(Elasticsearch), 상품 · 판매자 이벤트로 색인, 검색어 이벤트 발행. search-service로 따로 뜸</td></tr><tr><td>정산</td><td>baiees</td><td>정산 대상, 영업일 일정산(Spring Batch), 지급 요청 · 결과 반영 (지갑 적립은 결제)</td></tr><tr><td>커뮤니티</td><td>L2J92</td><td>리뷰(작성 자격 · 작성 · 목록 · 요약) · 찜 — review · favorite 컨텍스트. 상품 · 주문 · 회원 이벤트만 받고 보내는 이벤트는 없음</td></tr><tr><td>공통</td><td>팀</td><td>오류 응답, 이벤트 형식(<code>shared</code> 계약), 이벤트 발행 · Kafka 규칙, 공통 설정, 요청 로그 · 모니터링, FE 동작 설정(setting 모듈). API Gateway(apps/gateway, maruhxn)</td></tr></tbody></table><h3 id="주문-모듈-구조-변경-세미-→-최종" tabindex="-1">주문 모듈 구조 변경 (세미 → 최종) <a class="header-anchor" href="#주문-모듈-구조-변경-세미-→-최종" aria-label="Permalink to &quot;주문 모듈 구조 변경 (세미 → 최종)&quot;">​</a></h3><p>주문은 다른 도메인과 Kafka 이벤트로만 연결되고, 외부 API 주소와 응답 형식은 세미 그대로입니다(필드 · 값 추가만).</p><table tabindex="0"><thead><tr><th>항목</th><th>세미</th><th>최종</th></tr></thead><tbody><tr><td>모듈</td><td>앱 안의 패키지, 공통 모듈(common)에 의존</td><td>독립 Gradle 모듈(<code>domains/order</code>), 공통 모듈 의존 제거</td></tr><tr><td>내부 구성</td><td>주문 한 덩어리</td><td>컨텍스트 4개(order 주문 · cart 장바구니 · delivery 배송 · wish 조르기), 컨텍스트끼리는 포트로만 연결</td></tr><tr><td>계층 구조</td><td>app · domain · in · out</td><td>같은 구조를 ArchUnit 테스트로 고정(계층 · 컨텍스트 경계 · 패키지 배치)</td></tr><tr><td>도메인 간 통신</td><td>Spring 이벤트(앱 안)</td><td>Kafka. 보내기는 아웃박스, 받기 실패는 DLT. 수신 스위치로 Spring 이벤트 경로 전환 가능</td></tr><tr><td>인증</td><td>앱의 공통 인증 필터</td><td>API Gateway가 검증, 주문은 헤더로 로그인 회원만 받음</td></tr><tr><td>DB 스키마</td><td>JPA 자동 생성</td><td>Flyway 마이그레이션</td></tr><tr><td>실패 복구</td><td>이벤트 처리 실패 · 결제 반영 실패를 관리자가 재처리</td><td>+ DLT 메시지도 관리자 화면에서 확인 · 재처리 · 종료</td></tr></tbody></table><h2 id="_3-3-모듈-연결-지도" tabindex="-1">3.3 모듈 연결 지도 <a class="header-anchor" href="#_3-3-모듈-연결-지도" aria-label="Permalink to &quot;3.3 모듈 연결 지도&quot;">​</a></h2><p>도메인 사이 이벤트는 모두 <strong>Kafka</strong>로 갑니다. 보내는 도메인마다 토픽이 하나이고, 받는 도메인은 자기 구독 그룹으로 필요한 종류만 받습니다. 최신 연결은 <a href="https://claude.ai/artifact/SsSBBKhQsFNFJVCXrPPtGU" target="_blank" rel="noreferrer">도메인 연결 지도</a>에서 볼 수 있습니다.</p><table tabindex="0"><thead><tr><th>보내는 쪽</th><th>토픽</th><th>이벤트 → 받는 쪽 (구독 그룹 <code>kidly.{받는도메인}</code>)</th></tr></thead><tbody><tr><td>회원</td><td><code>kidly.member.events</code></td><td><code>member.registered</code> → 결제 · 알림 · <code>member.changed</code> → 판매자 · <code>member.withdrawn</code> → 자녀 프로필 · 결제 (추천 · 커뮤니티 예정) · <code>member.tokens-revoked</code> → Gateway</td></tr><tr><td>판매자</td><td><code>kidly.seller.events</code></td><td><code>seller.changed</code> → 회원 · 상품 · 주문 · 추천 · 검색</td></tr><tr><td>자녀 프로필</td><td><code>kidly.childprofile.events</code></td><td><code>child.changed</code> → 주문 · 추천</td></tr><tr><td>상품</td><td><code>kidly.product.events</code></td><td><code>product.changed</code> → 주문 · 추천 · 검색 · 커뮤니티 · <code>stock.deducted</code> · <code>stock.deduction-failed</code> → 주문</td></tr><tr><td>주문</td><td><code>kidly.order.events</code></td><td><code>order.created</code> → 상품 · <code>order.payment-requested</code> → 결제 · <code>order.cancelled</code> → 상품 · 결제 · <code>order-item.purchase-confirmed</code> → 정산 · 추천 · 커뮤니티 · <code>order-item.cancelled</code> → 결제 · 상품 · <code>cart.item-added</code> → (추천 예정)</td></tr><tr><td>결제</td><td><code>kidly.payment.events</code></td><td><code>payment.completed</code> · <code>payment.failed</code> → 주문 · <code>payment.payout-completed</code> · <code>payment.payout-failed</code> → 정산</td></tr><tr><td>정산</td><td><code>kidly.settlement.events</code></td><td><code>settlement.payout-requested</code> → 결제 (dev 켬, prod는 main 반영 때)</td></tr><tr><td>검색</td><td><code>kidly.search.events</code></td><td><code>search.performed</code> → (추천 예정)</td></tr></tbody></table><ul><li>결제 · 주문 · 정산 · 상품 · 커뮤니티에는 Spring 이벤트 수신 코드도 남아 있습니다. Kafka 수신 스위치를 끌 때 되돌아가는 길입니다. 판매자 부분 취소(<code>order-item.cancelled</code>)는 Kafka로만 받습니다.</li><li>다른 도메인 정보가 필요하면 이벤트로 받아 <strong>자기 복사본</strong>을 둡니다 (6.3). 예: 추천은 자녀 정보 · 상품 사이즈 정보를, 주문은 자녀 정보 · 상품 가격을 복사본으로 가집니다.</li><li><strong>🕒 = 시간에 따라 실행되는 작업</strong> (주문: 결제 제한 시간 만료 · 자동 구매확정 · 택배 조회 · 아웃박스 릴레이 / 정산: 영업일 일정산(Spring Batch) · 지급 결과 재요청 · 아웃박스 릴레이 / 결제: 충전 정리 · 주문 취소 환불 재처리 · 아웃박스 릴레이 · 정리 / 상품 · 자녀 프로필: 아웃박스 릴레이 / 알림: 메일 재발송 / 회원: 만료된 Refresh Token 정리)</li><li>다른 모듈의 테이블은 직접 읽지 않습니다. 도메인 사이에는 FK를 두지 않고, 다른 모듈의 ID는 값으로만 저장합니다.</li></ul><p>아래는 세미 때 그림(Spring 이벤트)입니다. 연결은 위 표가 기준입니다.</p><p><img src="'+i+'" alt="Kidly 모듈 통신도"></p><h2 id="_3-4-주문-전까지" tabindex="-1">3.4 주문 전까지 <a class="header-anchor" href="#_3-4-주문-전까지" aria-label="Permalink to &quot;3.4 주문 전까지&quot;">​</a></h2><p>주문 · 추천은 회원 · 상품에 묻지 않고, 미리 받아 둔 <strong>복사본</strong>을 씁니다 (6.3). 실선 = 사용자 요청, 점선 = 이벤트. 그림은 세미 기준이고, 지금 점선의 이벤트는 Kafka로 갑니다(3.3).</p><p><strong>① 판매자가 되기까지</strong></p><p><img src="'+s+'" alt="판매자가 되기까지"></p><p><strong>② 보호자가 장바구니에 담기까지</strong></p><p><img src="'+l+'" alt="보호자가 장바구니에 담기까지"></p><h2 id="_3-5-구매에서-정산까지" tabindex="-1">3.5 구매에서 정산까지 <a class="header-anchor" href="#_3-5-구매에서-정산까지" aria-label="Permalink to &quot;3.5 구매에서 정산까지&quot;">​</a></h2><p><img src="'+n+'" alt="그림"></p><p>결제는 주문 · 상품을 부르지 않고, 받은 이벤트로만 움직입니다. 결제 결과 · 지급 결과는 지갑을 바꾼 트랜잭션에서 아웃박스에 저장한 뒤 보내므로 「돈은 빠졌는데 알림이 사라지는」 일이 없습니다.</p><p>실선 = 사용자 요청, 점선 = 이벤트. 번호 순서대로 7장의 ④ → ⑦ 카드가 이어집니다.</p><h2 id="_3-6-추천-서비스-데이터-흐름" tabindex="-1">3.6 추천 서비스 데이터 흐름 <a class="header-anchor" href="#_3-6-추천-서비스-데이터-흐름" aria-label="Permalink to &quot;3.6 추천 서비스 데이터 흐름&quot;">​</a></h2><p>실선 = 사용자 요청, 점선 = Kafka 이벤트.</p><p><img src="'+h+'" alt="그림"></p><ul><li>주문 · 결제 경로에는 추천 서비스가 없습니다. 추천 서비스가 멈추면 Gateway가 3초 뒤 끊고 화면은 추천 영역만 비웁니다.</li><li>계산은 이벤트가 올 때 합니다(복사본 · 임베딩 · 선호 점수). 요청이 올 때는 저장된 것을 읽고, AI 호출은 홈 맛보기와 함께 사면 좋은 상품에만, 같은 입력이면 저장된 응답을 재사용합니다.</li></ul><h2 id="_3-7-결제-서비스-이벤트-흐름" tabindex="-1">3.7 결제 서비스 이벤트 흐름 <a class="header-anchor" href="#_3-7-결제-서비스-이벤트-흐름" aria-label="Permalink to &quot;3.7 결제 서비스 이벤트 흐름&quot;">​</a></h2><p>실선 = 요청 · 저장, 점선 = Kafka.</p><p><img src="'+p+'" alt="그림"></p><p>결제는 다른 도메인을 부르지 않습니다. 화면 요청(충전 · 조회)과 이벤트만 받고, 결과는 이벤트로만 알립니다. 그래서 결제를 다른 서비스로 떼어도 다른 도메인의 코드는 바뀌지 않습니다.</p><h2 id="_3-8-검색-서비스-흐름" tabindex="-1">3.8 검색 서비스 흐름 <a class="header-anchor" href="#_3-8-검색-서비스-흐름" aria-label="Permalink to &quot;3.8 검색 서비스 흐름&quot;">​</a></h2><p><img src="'+m+'" alt="그림"></p><p>검색은 상품 DB를 읽지 않고 상품 · 판매자 이벤트로 색인합니다. 검색 서비스가 멈추면 상품 목록만 503이고, 상품 상세 · 장바구니 · 주문은 kidly-app이 받아 그대로 동작합니다.</p>',39)])])}const C=e(_,[["render",g]]);export{B as __pageData,C as default};
